/* =====================================================================
   EDUCASEG-PLUS — Service Worker (aplicativo instalável e uso offline)
   Coloque este arquivo como "sw.js" na MESMA pasta do index.html
   (raiz do repositório publicado no GitHub Pages).
   Ele fornece: manifesto do aplicativo, ícones, cache das bibliotecas
   e funcionamento offline do sistema. Os dados da API (Google Sheets)
   nunca são guardados pelo service worker.
   ===================================================================== */
const VERSAO = 'educaseg-plus-v2.4.0';
const CACHE_APP = VERSAO + '-app';
const CACHE_LIB = VERSAO + '-lib';

const BIBLIOTECAS = [
    'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js',
    'https://cdnjs.cloudflare.com/ajax/libs/leaflet.heat/0.2.0/leaflet-heat.js',
    'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'
];

const ICONES = {"icon-192.png":"","icon-512.png":"","icon-maskable-512.png":""};

const MANIFESTO = {
    name: 'EDUCASEG-PLUS — Inteligência em Segurança Escolar',
    short_name: 'EDUCASEG+',
    description: 'Verificação de rotas, fragilidades, recorrências e problemas da segurança escolar em Mato Grosso.',
    lang: 'pt-BR',
    start_url: './index.html#painel',
    scope: './',
    display: 'standalone',
    display_override: ['window-controls-overlay', 'standalone'],
    orientation: 'any',
    background_color: '#0b1424',
    theme_color: '#0b1424',
    categories: ['education', 'productivity', 'government'],
    icons: [
        { src: 'icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: 'icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
        { src: 'icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' }
    ],
    shortcuts: [
        { name: 'Problemas detectados', url: './index.html#alertas', icons: [{ src: 'icon-192.png', sizes: '192x192' }] },
        { name: 'Mapa de MT', url: './index.html#mapa', icons: [{ src: 'icon-192.png', sizes: '192x192' }] },
        { name: 'Gráficos', url: './index.html#graficos', icons: [{ src: 'icon-192.png', sizes: '192x192' }] }
    ]
};

function png(nome) {
    const bin = atob(ICONES[nome]); const u = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    return new Response(u, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800' } });
}

self.addEventListener('install', e => {
    e.waitUntil((async () => {
        const app = await caches.open(CACHE_APP);
        await app.addAll(['./', './index.html']).catch(() => {});
        const lib = await caches.open(CACHE_LIB);
        await Promise.all(BIBLIOTECAS.map(u => fetch(u, { mode: 'cors' }).then(r => r.ok && lib.put(u, r)).catch(() => {})));
        await self.skipWaiting();
    })());
});

self.addEventListener('activate', e => {
    e.waitUntil((async () => {
        const nomes = await caches.keys();
        await Promise.all(nomes.filter(n => n.startsWith('educaseg-plus-') && !n.startsWith(VERSAO)).map(n => caches.delete(n)));
        await self.clients.claim();
    })());
});

self.addEventListener('message', e => { if (e.data === 'ATUALIZAR') self.skipWaiting(); });

self.addEventListener('fetch', e => {
    const req = e.request;
    if (req.method !== 'GET') return;                         // POST da API passa direto
    const url = new URL(req.url);

    // API do Google Apps Script: nunca usar cache (dados sigilosos)
    if (/script\.google(usercontent)?\.com$/.test(url.hostname)) return;

    // Manifesto e ícones gerados aqui mesmo
    if (url.origin === self.location.origin) {
        const arq = url.pathname.split('/').pop();
        if (arq === 'manifest.webmanifest') return e.respondWith(new Response(JSON.stringify(MANIFESTO), { headers: { 'Content-Type': 'application/manifest+json' } }));
        if (ICONES[arq]) return e.respondWith(png(arq));
    }

    // Navegação: rede primeiro (versão mais nova), cache se estiver offline
    if (req.mode === 'navigate') {
        return e.respondWith((async () => {
            try {
                const r = await fetch(req);
                if (r.ok) (await caches.open(CACHE_APP)).put('./index.html', r.clone());
                return r;
            } catch (err) {
                return (await caches.match('./index.html')) || (await caches.match('./')) || new Response('<h1>EDUCASEG-PLUS</h1><p>Sem conexão e sem cópia local. Conecte-se e abra o sistema uma vez.</p>', { headers: { 'Content-Type': 'text/html; charset=utf-8' } });
            }
        })());
    }

    // Bibliotecas (cdnjs): cache primeiro
    if (url.hostname === 'cdnjs.cloudflare.com') {
        return e.respondWith((async () => {
            const c = await caches.match(req); if (c) return c;
            const r = await fetch(req); if (r.ok) (await caches.open(CACHE_LIB)).put(req, r.clone()); return r;
        })());
    }

    // Fontes do Google: usa o cache e atualiza em segundo plano
    if (/fonts\.(googleapis|gstatic)\.com$/.test(url.hostname)) {
        return e.respondWith((async () => {
            const cache = await caches.open(CACHE_LIB), c = await cache.match(req);
            const rede = fetch(req).then(r => { if (r.ok || r.type === 'opaque') cache.put(req, r.clone()); return r; }).catch(() => c);
            return c || rede;
        })());
    }
});
